    if (
        !arePreloadBitmapsReady(
            pendingTalkPreload.bitmaps
        )
    ) {
        return true;
    }

    const talk =
        pendingTalkPreload.talk;

    pendingTalkPreload = null;

    enqueueTalkMessageNow(talk);

    return true;
